return $input.all().map((it, i) => { const ctx = $('Build QA request').all()[i].json; const json = it.json; const raw = json.choices?.[0]?.message?.content ?? ''; let out; try { out = JSON.parse(raw.replace(/^```(json)?|```$/g, '').trim()); } catch (e) { throw new Error('LLM did not return JSON: ' + raw.slice(0, 300)); }
  const pass = out.verdict === 'PASS'; return { json: { ...ctx, body: undefined, qa: out, pass, retry: !pass && ctx.attempt < 1,
